import re, ast
lines = open('output.log', errors='replace').read().splitlines()
rollout, perf, train, evl = {}, {}, {}, {}
for ln in lines:
    m = re.search(r"data\.py:\d+ - rollout (\d+): (\{.*\})", ln)
    if m:
        rollout[int(m.group(1))] = ast.literal_eval(m.group(2)); continue
    m = re.search(r"rollout\.py:\d+ - perf (\d+): (\{.*\})", ln)
    if m:
        perf[int(m.group(1))] = ast.literal_eval(m.group(2)); continue
    m = re.search(r"train (\d+): (\{.*\})", ln)
    if m:
        train[int(m.group(1))] = ast.literal_eval(m.group(2)); continue
    m = re.search(r"eval (\d+): (\{.*\})", ln)
    if m:
        evl[int(m.group(1))] = ast.literal_eval(m.group(2))
print("counts: rollout",len(rollout),"perf",len(perf),"train",len(train),"eval",len(evl))
if train:
    print("\ntrain keys:", sorted(train[list(train)[0]]))
if rollout:
    print("\nrollout keys:", sorted(rollout[0]))
EOF
